    gap: 1rem;
    margin-top: 1rem;
    align-items: flex-start;
}

/* Stats bar */
.board-stats {
    display: flex;
    gap: 1.5rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    margin-bottom: 1rem;
}

.stat-item {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-value {
    font-size: 1.5rem;
    font-weight: 700;
}

.stat-label {
    font-size: 0.8rem;
    color: #6c757d;
}

.stat-overdue .stat-value {
    color: #dc3545;
}

/* Search bar */
.board-search {
    margin-bottom: 1rem;
    max-width: 400px;
}

/* Column */
.board-column {
    flex: 1;
    background: #f1f3f5;
    border-radius: 0.5rem;
    padding: 0.75rem;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.board-column-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.board-column-header h5 {
    margin: 0;
}

.board-column-body {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    min-height: 50px;
}

.board-column-footer {
    margin-top: 0.75rem;
}

/* Task card */
.task-card {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.task-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.task-title {
    font-weight: 600;
}

.priority-badge {
    padding: 0.15rem 0.5rem;
    border-radius: 0.25rem;
    font-size: 0.75rem;
    font-weight: 600;
    color: #fff;
}

.priority-high {
    background-color: #dc3545;
}

.priority-medium {
    background-color: #ffc107;
    color: #212529;
}

.priority-low {
    background-color: #28a745;
}

.task-card-body {
    display: flex;
    justify-content: space-between;
    font-size: 0.85rem;
    color: #495057;
    margin-bottom: 0.5rem;
}

.task-card-actions {
    display: flex;
    gap: 0.5rem;
}

/* Add task form */
.add-task-form {
    background: #fff;
    border: 1px dashed #adb5bd;
    border-radius: 0.375rem;
    padding: 0.75rem;
}

.add-task-btn {
    width: 100%;
}

